// Package policy evaluates deterministic first-match-wins rules against a
// decision result. This is where mrmr's core invariant lives: the model
// recommends, the runtime decides. Everything here is pure evaluation —
// no I/O, no time, no randomness — so a given (rules, result) pair always
// produces the same outcome, which is what makes policy inspectable and
// trustworthy. Condition semantics are deliberately minimal (ANDed
// conditions, literal equality or a handful of operators, first match wins,
// no OR or nesting); anything richer is a later addition, not a v0 gap.
package policy

import (
	"fmt"
	"strconv"
	"strings"
)

// Notify describes a notification outcome. Via names the adapter; v0.1
// ships only stdout. Message is a Go template executed over the decision
// result so flows can surface the model's own summary.
type Notify struct {
	Via     string `yaml:"via"`
	Message string `yaml:"message"` // Go template over {result: ...}; empty = summary default
}

// Then is the selected outcome for an event. Exactly one action is set;
// config validation enforces that, and the runtime trusts it.
type Then struct {
	Notify *Notify `yaml:"notify"`
	Ignore bool    `yaml:"ignore"`
}

func (t Then) Outcome() string {
	switch {
	case t.Notify != nil:
		return "notify"
	default:
		return "ignore"
	}
}

// Rule is one policy line: ANDed conditions and the outcome they select.
type Rule struct {
	If   map[string]any `yaml:"if"` // ANDed; value is literal or operator string
	Then Then           `yaml:"then"`
}

// Policy is the ordered rule list plus the fall-through default. Order is
// significant: rules evaluate top to bottom and the first match wins, so a
// policy file reads like the author's priority order.
type Policy struct {
	Rules   []Rule `yaml:"policy"`
	Default Then   `yaml:"default"`
}

// Evaluate returns the outcome of the first rule whose conditions all match,
// or the default. The second return value is the matched rule's index into
// Rules (0-based), or -1 when the default applied — the trace needs to say
// *which* rule fired, not just what it did, or "why did this happen?" is
// half-answered. A condition naming a field the result doesn't have simply
// doesn't match — missing data must fall through to less aggressive
// outcomes, never block them.
func (p Policy) Evaluate(result map[string]any) (Then, int) {
	for i, r := range p.Rules {
		if matchesAll(r.If, result) {
			return r.Then, i
		}
	}
	return p.Default, -1
}

func matchesAll(conds map[string]any, result map[string]any) bool {
	for key, want := range conds {
		path := strings.TrimPrefix(key, "result.")
		got, ok := result[path]
		if !ok {
			return false
		}
		if !match(want, got) {
			return false
		}
	}
	return true
}

// match compares a condition value against the actual result value. A
// string condition is either an operator expression ("> 0.8") or a literal
// for equality; anything else (numbers, booleans) is a literal. Comparison
// is by fmt.Sprint so YAML scalars and JSON values line up without a
// type-coercion matrix.
func match(want any, got any) bool {
	if w, ok := want.(string); ok {
		if op, operand, isOp := parseOperator(w); isOp {
			return compareOp(op, operand, got)
		}
	}
	return fmt.Sprint(want) == fmt.Sprint(got)
}

var ops = []string{">=", "<=", "!=", ">", "<"}

// parseOperator recognizes "> x", ">= x", "< x", "<= x", "!= x".
func parseOperator(s string) (op, operand string, ok bool) {
	s = strings.TrimSpace(s)
	for _, o := range ops {
		if strings.HasPrefix(s, o) {
			return o, strings.TrimSpace(s[len(o):]), true
		}
	}
	return "", "", false
}

// compareOp applies an operator. Numeric comparison requires both sides to
// parse as numbers; ordering operators on non-numbers are false rather than
// an error, which keeps evaluation pure and total. "!" is the one operator
// that also makes sense for strings.
func compareOp(op, operand string, got any) bool {
	g, err1 := strconv.ParseFloat(fmt.Sprint(got), 64)
	w, err2 := strconv.ParseFloat(operand, 64)
	numeric := err1 == nil && err2 == nil
	switch op {
	case "!=":
		if numeric {
			return g != w
		}
		return fmt.Sprint(got) != operand
	case ">":
		return numeric && g > w
	case ">=":
		return numeric && g >= w
	case "<":
		return numeric && g < w
	case "<=":
		return numeric && g <= w
	}
	return false
}

// Package config loads and validates the mrmr YAML config. Validation happens
// before anything is activated: an invalid config must fail startup loudly
// rather than produce a runtime that silently misbehaves (a policy with no
// then, a model that doesn't exist). Config is the only place mrmr's behavior
// is described, so it is also the first place to look when behavior surprises.
package config

import (
	"bytes"
	"fmt"
	"math"
	"os"

	"gopkg.in/yaml.v3"

	"github.com/heath0xff/mrmr/internal/filter"
	"github.com/heath0xff/mrmr/internal/model"
	"github.com/heath0xff/mrmr/internal/policy"
)

type Server struct {
	Addr string `yaml:"addr"`
}

type DB struct {
	Path string `yaml:"path"`
}

type Interpret struct {
	Model  string       `yaml:"model"`
	Prompt string       `yaml:"prompt"`
	Schema model.Schema `yaml:"schema"`
}

type Config struct {
	Server Server `yaml:"server"`
	DB     DB     `yaml:"db"`
	// Filter is the pre-model gate (IMPLEMENTATION.md section 3):
	// deterministic checks that run before any model call. An event
	// that fails any Spec is recorded and ignored before
	// interpretation.
	Filter    filter.List             `yaml:"filter"`
	Models    map[string]model.Config `yaml:"models"`
	Interpret Interpret               `yaml:"interpret"`
	// Policy is inlined so the YAML reads exactly like IMPLEMENTATION.md:
	// a top-level `policy:` list plus a sibling `default:`.
	Policy policy.Policy `yaml:"policy,inline"`
}

// Load reads, parses, and validates the config at path. Defaults (addr,
// db path) are applied for the values a minimal local setup never needs to
// set; anything the runtime cannot run correctly without stays required.
// Decoding is strict — unknown keys are errors, not warnings — because a
// typo like `api_keyenv:` silently disabling auth is far worse than a
// refused startup.
func Load(path string) (*Config, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read config %s: %w", path, err)
	}
	var c Config
	d := yaml.NewDecoder(bytes.NewReader(b))
	d.KnownFields(true)
	if err := d.Decode(&c); err != nil {
		return nil, fmt.Errorf("parse config %s: %w", path, err)
	}
	if c.Server.Addr == "" {
		c.Server.Addr = ":4242"
	}
	if c.DB.Path == "" {
		c.DB.Path = "mrmr.db"
	}
	if err := c.Validate(); err != nil {
		return nil, err
	}
	return &c, nil
}

func (c *Config) Validate() error {
	if c.Interpret.Model == "" {
		return fmt.Errorf("config: interpret.model is required")
	}
	mc, ok := c.Models[c.Interpret.Model]
	if !ok {
		return fmt.Errorf("config: interpret.model %q not defined in models", c.Interpret.Model)
	}
	if mc.Provider != "openai-compatible" {
		return fmt.Errorf("config: model %q: unsupported provider %q (v0.1: openai-compatible)", c.Interpret.Model, mc.Provider)
	}
	if mc.BaseURL == "" {
		return fmt.Errorf("config: model %q: base_url is required", c.Interpret.Model)
	}
	if c.Interpret.Prompt == "" {
		return fmt.Errorf("config: interpret.prompt is required")
	}
	if len(c.Interpret.Schema) == 0 {
		return fmt.Errorf("config: interpret.schema is required")
	}
	for name, f := range c.Interpret.Schema {
		switch f.Type {
		case "string", "number", "boolean":
		default:
			return fmt.Errorf("config: schema field %q: unsupported type %q", name, f.Type)
		}
		if f.Type != "number" && (f.Minimum != nil || f.Maximum != nil) {
			return fmt.Errorf("config: schema field %q: minimum/maximum require type number", name)
		}
		if (f.Minimum != nil && (math.IsNaN(*f.Minimum) || math.IsInf(*f.Minimum, 0))) ||
			(f.Maximum != nil && (math.IsNaN(*f.Maximum) || math.IsInf(*f.Maximum, 0))) {
			return fmt.Errorf("config: schema field %q: minimum/maximum must be finite", name)
		}
		if f.Minimum != nil && f.Maximum != nil && *f.Minimum > *f.Maximum {
			return fmt.Errorf("config: schema field %q: minimum must not exceed maximum", name)
		}
	}
	for i, f := range c.Filter {
		if err := f.Validate(); err != nil {
			return fmt.Errorf("config: filter %d: %w", i+1, err)
		}
	}

	validateThen := func(t policy.Then, where string) error {
		// A rule that sets both notify and ignore is almost certainly a YAML
		// typo (a leftover ignore under a new notify). Rather than picking a
		// winner, reject it: ambiguity in outcome selection is exactly the
		// kind of thing policy must never have.
		if t.Notify != nil && t.Ignore {
			return fmt.Errorf("config: %s: set either notify or ignore, not both", where)
		}
		if t.Notify != nil && t.Notify.Via != "stdout" {
			return fmt.Errorf("config: %s: notify.via %q not supported (v0.1: stdout)", where, t.Notify.Via)
		}
		if t.Notify == nil && !t.Ignore {
			return fmt.Errorf("config: %s: must set notify or ignore: true", where)
		}
		return nil
	}
	for i, r := range c.Policy.Rules {
		if len(r.If) == 0 {
			return fmt.Errorf("config: policy rule %d: empty if", i+1)
		}
		if err := validateThen(r.Then, fmt.Sprintf("policy rule %d", i+1)); err != nil {
			return err
		}
	}
	return validateThen(c.Policy.Default, "default")
}

// Package event defines the two records that flow through mrmr's pipeline:
// the Event (what happened, normalized) and the Decision (what the model
// thought it meant). These types are intentionally boring and dependency-
// free — every stage of the runtime handles them, so any cleverness here
// would be paid for everywhere. data and metadata are opaque maps: the
// core makes no assumptions about what a source puts in them, because
// assuming is how source-specific logic leaks into the runtime.
package event

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"time"
)

// Event is the normalized record of something that happened. Sources are
// dumb by design: they detect and emit, they never interpret. The runtime
// stamps ID and Timestamp at ingestion — a source's clock is not trusted,
// though a source may carry its original time inside data or metadata if
// the event itself needs it.
type Event struct {
	ID        string         `json:"id"`
	Type      string         `json:"type"`
	Source    string         `json:"source"`
	Subject   string         `json:"subject,omitempty"`
	Timestamp time.Time      `json:"timestamp"` // event time, UTC
	Data      map[string]any `json:"data,omitempty"`
	Metadata  map[string]any `json:"metadata,omitempty"`
}

// Decision is the validated result of interpreting an Event. Status is the
// axis the rest of the runtime cares about: "ok" decisions reach policy;
// "invalid" (schema failure after retry) and "errored" (endpoint failure)
// both route to ignore. Decisions persist even when they fail, because "the
// model was down at 3am" is a question worth answering from the audit trail.
type Decision struct {
	ID          string         `json:"id"`
	EventID     string         `json:"event_id"`
	Interpreter string         `json:"interpreter"` // model config name
	Model       string         `json:"model"`       // actual model id sent to endpoint
	Status      string         `json:"status"`
	Result      map[string]any `json:"result,omitempty"`
	LatencyMs   int64          `json:"latency_ms"`
	Error       string         `json:"error,omitempty"`
}

// NewID returns a sortable unique id: prefix + hex(unix-millis + random).
// ponytail: hand-rolled instead of a ULID dep; swap if cross-system ordering matters.
func NewID(prefix string) string {
	var b [10]byte
	ms := time.Now().UnixMilli()
	for i := 0; i < 6; i++ {
		b[i] = byte(ms >> (8 * (5 - i)))
	}
	if _, err := rand.Read(b[6:]); err != nil {
		panic(fmt.Sprintf("new id: %v", err))
	}
	return prefix + hex.EncodeToString(b[:])
}

// Command mrmr is the single binary for the mrmr runtime. `run` loads a YAML
// config, opens SQLite, and serves POST /api/events. Each request is
// processed synchronously: the event is persisted; duplicates short-circuit
// there with a "duplicate" marker; and the rest run deterministic filters,
// model interpretation, policy, and outcome in order, with filter-excluded
// events stopping before the model call. The HTTP response is the trace of
// everything that happened. Synchronous processing is the point: it makes
// the runtime's behavior explainable end to end and keeps the invariants
// simple (no queue, no worker goroutines, no lost requests) at the cost of
// latency, which is fine for ambient event volumes.
package main

import (
	"context"
	"encoding/json"
	"flag"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/heath0xff/mrmr/internal/config"
	"github.com/heath0xff/mrmr/internal/event"
	"github.com/heath0xff/mrmr/internal/model"
	"github.com/heath0xff/mrmr/internal/runtime"
	"github.com/heath0xff/mrmr/internal/storage"
)

func main() {
	log.SetFlags(log.LstdFlags | log.LUTC)

	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "usage: mrmr <run|eval|events|label|dataset> [options]")
		os.Exit(2)
	}

	switch os.Args[1] {
	case "run":
		if err := run(os.Args[2:]); err != nil {
			log.Fatal(err)
		}
	case "eval":
		if err := eval(os.Args[2:]); err != nil {
			log.Fatal(err)
		}
	case "events":
		if err := events(os.Args[2:]); err != nil {
			log.Fatal(err)
		}
	case "label":
		if err := label(os.Args[2:]); err != nil {
			log.Fatal(err)
		}
	case "dataset":
		if err := dataset(os.Args[2:]); err != nil {
			log.Fatal(err)
		}
	case "-h", "--help", "help":
		fmt.Println("usage: mrmr <run|eval|events|label|dataset> [options]")
	default:
		log.Fatalf("unknown subcommand %q", os.Args[1])
	}
}

// run boots the server and blocks until SIGINT/SIGTERM. Shutdown is graceful
// because an in-flight event is mid-pipeline: killing it between the event
// persist and the decision persist would leave a half-processed event with
// no way to tell from outside whether anything was lost.
func run(args []string) error {
	fs := flag.NewFlagSet("mrmr run", flag.ContinueOnError)
	configPath := fs.String("config", "mrmr.yaml", "path to config file")
	if err := fs.Parse(args); err != nil {
		return err
	}

	cfg, err := config.Load(*configPath)
	if err != nil {
		return err
	}

	db, err := storage.Open(cfg.DB.Path)
	if err != nil {
		return err
	}
	defer db.Close()

	rt := &runtime.Runtime{
		DB:       db,
		Client:   &model.Client{},
		ModelCfg: cfg.Models[cfg.Interpret.Model],
		ModelKey: cfg.Interpret.Model,
		Prompt:   cfg.Interpret.Prompt,
		Schema:   cfg.Interpret.Schema,
		Policy:   cfg.Policy,
		Filters:  cfg.Filter,
	}

	mux := http.NewServeMux()
	mux.HandleFunc("POST /api/events", eventsHandler(rt))

	srv := &http.Server{Addr: cfg.Server.Addr, Handler: mux}

	// Cancel the context on SIGINT/SIGTERM so Shutdown has a deadline and a
	// second signal still hard-exits.
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	errCh := make(chan error, 1)
	go func() { errCh <- srv.ListenAndServe() }()

	log.Printf("mrmr listening on %s (db: %s, model: %s)", cfg.Server.Addr, cfg.DB.Path, cfg.Interpret.Model)

	select {
	case err := <-errCh:
		return err
	case <-ctx.Done():
	}

	// Bound shutdown so a hung request can't wedge the process; the pipeline
	// itself also respects ctx via the request context.
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := srv.Shutdown(shutdownCtx); err != nil {
		return fmt.Errorf("shutdown: %w", err)
	}
	return nil
}

// eventsRequest is the wire shape for POST /api/events. Only type and source
// are required; data and metadata are opaque maps passed through to the event.
type eventsRequest struct {
	Type     string         `json:"type"`
	Source   string         `json:"source"`
	Subject  string         `json:"subject,omitempty"`
	Data     map[string]any `json:"data,omitempty"`
	Metadata map[string]any `json:"metadata,omitempty"`
}

// eventsHandler returns the POST /api/events handler. Ingest is
// synchronous: by the time the 200 goes out, the event's fate is final:
// a duplicate, a filter exclusion before any model call, or an executed
// policy outcome. Ingest errors are persistence
// failures and map to 500; everything the model does wrong is already
// captured in the decision and trace, not in the HTTP status.
func eventsHandler(rt *runtime.Runtime) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		// This is the runtime's only external ingress, so bodies are bounded:
		// a normalized event is small, and one oversized POST must not be able
		// to eat memory. 1 MiB is generous headroom over any real event.
		r.Body = http.MaxBytesReader(w, r.Body, 1<<20)
		var req eventsRequest
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			writeError(w, http.StatusBadRequest, "malformed JSON body: "+err.Error())
			return
		}
		if req.Type == "" || req.Source == "" {
			writeError(w, http.StatusBadRequest, "both \"type\" and \"source\" are required")
			return
		}

		e := event.Event{
			ID:        event.NewID("evt_"),
			Type:      req.Type,
			Source:    req.Source,
			Subject:   req.Subject,
			Timestamp: time.Now().UTC(),
			Data:      req.Data,
			Metadata:  req.Metadata,
		}

		resp, err := rt.Ingest(r.Context(), e)
		if err != nil {
			// Persistence failed, which means the event's fate is unknown
			// to the caller; 500 (not 4xx) so clients may retry.
			log.Printf("ingest %s failed: %v", e.ID, err)
			writeError(w, http.StatusInternalServerError, "ingest failed")
			return
		}

		// One line per event so stdout doubles as a processing log. This is
		// the whole observability story for milestone 1: the response JSON
		// contains the decision and the full trace.
		b, err := json.Marshal(resp)
		if err != nil {
			writeError(w, http.StatusInternalServerError, "encode response: "+err.Error())
			return
		}
		fmt.Println(string(b))

		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusOK)
		w.Write(b)
	}
}

// writeError responds with the {"error": ...} envelope. Errors never carry
// internal detail beyond what the trace already exposes.
func writeError(w http.ResponseWriter, code int, msg string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	json.NewEncoder(w).Encode(map[string]string{"error": msg})
}

